<?php session_start(); require __DIR__.'/config.php'; if(empty($_SESSION['user'])){header('Location: auth.php');exit;} $st=db()->prepare("SELECT o.*,GROUP_CONCAT(CONCAT(oi.quantity,' × ',oi.size_name,' ',f.name) SEPARATOR ', ') detail FROM orders o JOIN order_items oi ON oi.order_id=o.id JOIN flavors f ON f.id=oi.flavor_id WHERE o.user_id=? GROUP BY o.id ORDER BY o.created_at DESC");$st->execute([$_SESSION['user']['id']]);$orders=$st->fetchAll(); ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mis pedidos | Milkito</title><link rel="stylesheet" href="assets/style.css"><style>.account{max-width:1000px;margin:auto;padding:55px 7%}.order-card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:22px;margin:15px 0;display:flex;justify-content:space-between;gap:20px}.order-card small{display:block;color:var(--muted);margin-top:7px}.badge{padding:8px 13px;border-radius:20px;background:#fff1c7;color:#9b6914;font-size:12px;height:max-content}.cancel{color:#c94b38;font-size:12px}.account-actions{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}@media(max-width:700px){.order-card{display:block}.badge{display:inline-block;margin-top:15px}}</style></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">M</span><span>adoquines <b>milkito</b></span></a><a href="index.php">Página principal</a></header><main class="account"><div class="account-actions"><div><p class="eyebrow">MI CUENTA</p><h1>Mis pedidos</h1><p>Hola, <?=e($_SESSION['user']['name'])?>. Aquí puedes seguir tus pedidos.</p></div><a class="btn btn-dark" href="index.php">Nuevo pedido →</a></div><?php foreach($orders as $o): ?><article class="order-card"><div><b>Pedido #<?=$o['id']?></b><p><?=e($o['detail'])?></p><small><?=e($o['address'])?> · <?=money((float)$o['total'])?></small><small><?=date('d/m/Y H:i',strtotime($o['created_at']))?></small><?php if($o['status']==='nuevo'): ?><small><a class="cancel" href="cancel_order.php?id=<?=$o['id']?>" onclick="return confirm('¿Cancelar este pedido?')">Cancelar pedido</a></small><?php endif; ?></div><span class="badge"><?=e(ucfirst($o['status']))?></span></article><?php endforeach; if(!$orders): ?><p>Aún no tienes pedidos registrados.</p><?php endif; ?></main></body></html>
